'use client';

import {
  Badge,
  ChoiceboxGroup,
  ChoiceboxGroupItem,
} from '@vercel/geistcn/components';
import { useState, type JSX } from 'react';

export function Component(): JSX.Element {
  const [value, setValue] = useState('trial');

  return (
    <ChoiceboxGroup
      label="select a plan"
      onChange={setValue}
      type="radio"
      value={value}
      listClassName="flex-row"
    >
      <ChoiceboxGroupItem
        description="Free for two weeks"
        title="Pro Trial"
        value="trial"
      >
        <div className="flex justify-center p-2">
          <Badge variant="trial">Trial</Badge>
        </div>
      </ChoiceboxGroupItem>
      <ChoiceboxGroupItem description="Get started now" title="Pro" value="pro">
        <div className="flex justify-center p-2">
          <Badge variant="blue">Pro</Badge>
        </div>
      </ChoiceboxGroupItem>
    </ChoiceboxGroup>
  );
}

export function Component(): JSX.Element {
  const [value, setValue] = useState(trial);
  return (
    <ChoiceboxGroup controlPosition="start" label="select a plan" onChange={setValue} type="radio" value={value}>
      <ChoiceboxGroupItem description="Free for two weeks" title="Pro Trial" value="trial" />
      <ChoiceboxGroupItem description="Get started now" title="Pro" value="pro" />
    </ChoiceboxGroup>
  );
}

